import assert from 'node:assert/strict';
import { createTokenBucket } from '../src/limiter/token-bucket.js';

const make = (options = { capacity: 3, refillPerSec: 1 }) => {
  const clock = { time: 0, now() { return this.time; } };
  return { clock, bucket: createTokenBucket({ ...options, clock }) };
};

// starts full; taking everything works and the next take fails
{
  const { bucket } = make();
  assert.equal(bucket.tokens(), 3);
  assert.equal(bucket.take(), true);
  assert.equal(bucket.tokens(), 2);
  assert.equal(bucket.take(2), true);
  assert.equal(bucket.tokens(), 0);
  assert.equal(bucket.take(), false);
  assert.equal(bucket.tokens(), 0);
}

// a take that asks for too much fails and removes nothing
{
  const { bucket } = make();
  assert.equal(bucket.take(4), false);
  assert.equal(bucket.tokens(), 3);
  bucket.take(2);
  assert.equal(bucket.take(2), false);
  assert.equal(bucket.tokens(), 1);
}

// tokens come back continuously at refillPerSec
{
  const { clock, bucket } = make();
  bucket.take(3);
  clock.time = 500;
  assert.equal(bucket.tokens(), 0.5);
  assert.equal(bucket.take(), false);
  clock.time = 1000;
  assert.equal(bucket.take(), true);
  assert.equal(bucket.take(), false);
}

// the refill rate counts: 2 tokens per second
{
  const { clock, bucket } = make({ capacity: 10, refillPerSec: 2 });
  bucket.take(10);
  clock.time = 1500;
  assert.equal(bucket.tokens(), 3);
}

// the bucket never holds more than its capacity
{
  const { clock, bucket } = make();
  clock.time = 60_000;
  assert.equal(bucket.tokens(), 3);
  assert.equal(bucket.take(4), false);
  bucket.take(3);
  clock.time = 120_000;
  assert.equal(bucket.tokens(), 3);
}

import assert from 'node:assert/strict';
import { createLru } from '../src/cache/lru.js';

const lru = createLru(2);
lru.set('a', 1);
lru.set('b', 2);
assert.equal(lru.get('a'), 1);
lru.set('c', 3);
// 'a' was just read, so it is the most recent and 'b' is evicted
assert.equal(lru.has('a'), true);
assert.equal(lru.has('b'), false);
assert.equal(lru.get('b'), undefined);
assert.deepEqual(lru.keys(), ['a', 'c']);
assert.equal(lru.size(), 2);

// writing an existing key refreshes it too, and does not grow the cache
const second = createLru(2);
second.set('a', 1);
second.set('b', 2);
second.set('a', 10);
second.set('c', 3);
assert.deepEqual(second.keys(), ['a', 'c']);
assert.equal(second.get('a'), 10);

// without reads or rewrites the oldest entry goes first
const third = createLru(3);
for (const key of ['x', 'y', 'z', 'w']) third.set(key, key);
assert.deepEqual(third.keys(), ['y', 'z', 'w']);
assert.equal(third.size(), 3);

assert.throws(() => createLru(0), RangeError);
assert.throws(() => createLru(1.5), RangeError);

import assert from 'node:assert/strict';
import { createTtlCache } from '../src/cache/ttl.js';

const clock = { time: 1_000_000, now() { return this.time; } };
const cache = createTtlCache({ clock, ttlMs: 1000 });

// the default ttl: alive just before it ends, gone at that instant
cache.set('default', 'd');
clock.time = 1_000_999;
assert.equal(cache.get('default'), 'd');
clock.time = 1_001_000;
assert.equal(cache.get('default'), undefined);

// a per-entry ttl and an absolute expiry
clock.time = 2_000_000;
cache.set('short', 1, { ttlMs: 5 });
cache.set('session', 'abc', { expiresAt: 2_500_000 });
assert.equal(cache.get('short'), 1);
assert.equal(cache.size(), 2);
clock.time = 2_000_005;
assert.equal(cache.size(), 1);
assert.equal(cache.get('short'), undefined);
assert.equal(cache.get('session'), 'abc');
clock.time = 2_499_999;
assert.equal(cache.get('session'), 'abc');
clock.time = 2_500_000;
assert.equal(cache.size(), 0);
assert.equal(cache.get('session'), undefined);

// setting a key again replaces its value and its expiry
clock.time = 3_000_000;
cache.set('k', 'old', { ttlMs: 10 });
cache.set('k', 'new', { ttlMs: 100 });
clock.time = 3_000_050;
assert.equal(cache.get('k'), 'new');

import assert from 'node:assert/strict';
import { createWindowLimiter } from '../src/limiter/window.js';

// Every check builds its own clock and limiter, so none sees another's hits.
function setup(options = { limit: 2, windowMs: 1000 }) {
  const clock = { time: 0, now() { return this.time; } };
  return { clock, limiter: createWindowLimiter({ ...options, clock }) };
}

// hits up to the limit are allowed, then refused
{
  const { limiter } = setup();
  assert.deepEqual(limiter.hit('u'), { allowed: true, remaining: 1, retryAfterMs: 0 });
  assert.deepEqual(limiter.hit('u'), { allowed: true, remaining: 0, retryAfterMs: 0 });
  const refused = limiter.hit('u');
  assert.equal(refused.allowed, false);
  assert.equal(refused.remaining, 0);
  assert.equal(limiter.hit('u').remaining, 0);
}

// the window ends exactly after windowMs, not before
{
  const { clock, limiter } = setup();
  limiter.hit('u');
  limiter.hit('u');
  clock.time = 999;
  assert.equal(limiter.hit('u').allowed, false);
  clock.time = 1000;
  assert.deepEqual(limiter.hit('u'), { allowed: true, remaining: 1, retryAfterMs: 0 });
}

// a refused hit says how long until the window ends
{
  const { clock, limiter } = setup();
  clock.time = 1200;
  limiter.hit('u');
  limiter.hit('u');
  assert.deepEqual(limiter.hit('u'), { allowed: false, remaining: 0, retryAfterMs: 1000 });
  clock.time = 1700;
  assert.deepEqual(limiter.hit('u'), { allowed: false, remaining: 0, retryAfterMs: 500 });
}

// keys have separate windows
{
  const { limiter } = setup();
  limiter.hit('a');
  limiter.hit('a');
  assert.equal(limiter.hit('a').allowed, false);
  assert.deepEqual(limiter.hit('b'), { allowed: true, remaining: 1, retryAfterMs: 0 });
}

// a limit of one
{
  const { limiter } = setup({ limit: 1, windowMs: 50 });
  assert.deepEqual(limiter.hit('x'), { allowed: true, remaining: 0, retryAfterMs: 0 });
  assert.equal(limiter.hit('x').allowed, false);
}
